36	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
37	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
38	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
41	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.PetDto;
43	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
46	import org.springframework.samples.petclinic.service.ClinicService;
47	import org.springframework.samples.petclinic.util.HouseholdNormalizer;
48	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /**
67	     * Syntactic validation for an owner email: a non-empty local part, an '@', and a dotted domain
68	     * whose top-level label is at least two letters. Deliberately conservative so plainly malformed
69	     * input (e.g. a value without an '@') is rejected.
70	     */
71	    private static final Pattern EMAIL_PATTERN =
72	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
73	
74	    private final ClinicService clinicService;
75	
76	    private final OwnerMapper ownerMapper;
77	
78	    private final PetMapper petMapper;
79	
80	    private final VisitMapper visitMapper;
81	
82	    public OwnerRestControllerV1(ClinicService clinicService,
83	                                 OwnerMapper ownerMapper,
84	                                 PetMapper petMapper,
85	                                 VisitMapper visitMapper) {
86	        this.clinicService = clinicService;
87	        this.ownerMapper = ownerMapper;
88	        this.petMapper = petMapper;
89	        this.visitMapper = visitMapper;
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
95	        Collection<Owner> owners;
96	        if (lastName != null) {
97	            owners = this.clinicService.findOwnerByLastName(lastName);
98	        } else {
99	            owners = this.clinicService.findAllOwners();
100	        }
101	        if (owners.isEmpty()) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
110	        Owner owner = this.clinicService.findOwnerById(ownerId);
111	        if (owner == null) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
120	        rejectBlankOwnerFields(ownerFieldsDto);
121	        normalizeTelephone(ownerFieldsDto);
122	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
123	        rejectDuplicateHousehold(ownerFieldsDto);
124	        normalizeEmail(ownerFieldsDto);
125	        HttpHeaders headers = new HttpHeaders();
126	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
127	        if (owner.getRegistrationDate() == null) {
128	            owner.setRegistrationDate(LocalDate.now());
129	        }
130	        this.clinicService.saveOwner(owner);
131	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
132	        headers.setLocation(UriComponentsBuilder.newInstance()
133	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
134	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
140	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
141	        if (currentOwner == null) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        currentOwner.setAddress(ownerFieldsDto.getAddress());
145	        currentOwner.setCity(ownerFieldsDto.getCity());
146	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
147	        currentOwner.setLastName(ownerFieldsDto.getLastName());
148	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
149	        normalizeEmail(ownerFieldsDto);
150	        currentOwner.setEmail(ownerFieldsDto.getEmail());
151	        this.clinicService.saveOwner(currentOwner);
152	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
153	    }
154	
155	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
156	    @Transactional
157	    @Override
158	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
159	        Owner owner = this.clinicService.findOwnerById(ownerId);
160	        if (owner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        this.clinicService.deleteOwner(owner);
164	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Override
169	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
170	        Owner owner = this.clinicService.findOwnerById(ownerId);
171	        if (owner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        HttpHeaders headers = new HttpHeaders();
175	        Pet pet = petMapper.toPet(petFieldsDto);
176	        owner.setId(ownerId);
177	        pet.setOwner(owner);
178	        pet.getType().setName(null);
179	        this.clinicService.savePet(pet);
180	        PetDto petDto = petMapper.toPetDto(pet);
181	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
182	            .buildAndExpand(pet.getId()).toUri());
